import React, { useState } from "react";

const OrderForm = () => {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    location: "",
    product: "",
    quantity: "",
    paymentMethod: "Mpesa"
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log("Order Submitted:", formData);
    alert("Your order has been placed successfully!");
  };

  return (
    <div className="max-w-lg mx-auto p-6 bg-white shadow-lg rounded-lg">
      <h2 className="text-2xl font-bold text-center mb-4">Place Your Order</h2>
      <form onSubmit={handleSubmit} className="space-y-4">
        <input type="text" name="name" value={formData.name} onChange={handleChange} placeholder="Full Name" required className="w-full p-2 border rounded" />
        <input type="email" name="email" value={formData.email} onChange={handleChange} placeholder="Email" required className="w-full p-2 border rounded" />
        <input type="text" name="phone" value={formData.phone} onChange={handleChange} placeholder="Phone Number" required className="w-full p-2 border rounded" />
        <input type="text" name="location" value={formData.location} onChange={handleChange} placeholder="Delivery Location" required className="w-full p-2 border rounded" />
        <select name="product" value={formData.product} onChange={handleChange} required className="w-full p-2 border rounded">
          <option value="">Select Product</option>
          <option value="Eggs">Eggs</option>
          <option value="Chicks">Chicks</option>
          <option value="Fully Grown Chickens">Fully Grown Chickens</option>
        </select>
        <input type="number" name="quantity" value={formData.quantity} onChange={handleChange} placeholder="Quantity" required className="w-full p-2 border rounded" />
        <select name="paymentMethod" value={formData.paymentMethod} onChange={handleChange} className="w-full p-2 border rounded">
          <option value="Mpesa">Mpesa</option>
          <option value="Cash on Delivery">Cash on Delivery</option>
        </select>
        <button type="submit" className="w-full p-2 bg-blue-500 text-white font-bold rounded hover:bg-blue-600">Submit Order</button>
      </form>
    </div>
  );
};

export default OrderForm;
